package ejercicio4;
import java.util.Scanner;
public class Ejercicio4 {

	public static void main(String[] args) {
		Scanner scanner = new Scanner(System.in);

        // Pedir la primera tirada
        System.out.print("¿Cuánto has sacado en la primera tirada? (UNO, DOS, TRES, CUATRO, CINCO o SEIS): ");
        String tirada1 = scanner.nextLine();

        // Pedir la segunda tirada
        System.out.print("¿Cuánto has sacado en la segunda tirada? (UNO, DOS, TRES, CUATRO, CINCO o SEIS): ");
        String tirada2 = scanner.nextLine();

        // Convertir las cadenas a números usando un método auxiliar
        int numero1 = Integer.parseInt (tirada1);
        int numero2 = Integer.parseInt                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           (tirada2);

        // Comprobar que los datos introducidos eran válidos
        if (numero1 == 0 || numero2 == 0) {
            System.out.println("Error: Has introducido un valor incorrecto. Debes escribir el número en letras (ej: UNO).");
        } else {
            // Calcular la suma
            int suma = numero1 + numero2;
            
            // Mostrar el resultado numérico
            System.out.println("\nLa suma de las dos tiradas es: " + suma);
        }
	}

}
